package edu.uao.yugioh.persistence; import edu.uao.yugioh.model.ResultadoCombate; import java.io.*; import java.nio.file.*; public class HistorialRepository { private final Path archivo; public HistorialRepository(String ruta){archivo=Paths.get(ruta);} public void guardar(ResultadoCombate r){try{Files.writeString(archivo,r+System.lineSeparator(),StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(IOException e){throw new UncheckedIOException("No se pudo guardar el historial",e);}} public String leer(){try{return Files.exists(archivo)?Files.readString(archivo):"";}catch(IOException e){throw new UncheckedIOException(e);}} }